"""Generate docs/compliance/requirements-matrix.md and risk-register.md from catalog.py, so the
documents and the Compliance screen can never disagree (spec 13, 23; HIMS-COMP)."""

from pathlib import Path

from . import catalog

DOCS = Path(__file__).resolve().parents[3] / "docs" / "compliance"
MATRIX = DOCS / "requirements-matrix.md"
RISKS = DOCS / "risk-register.md"
HEADER = (
    "<!-- Generated by `python manage.py compliance_docs` from "
    "backend/apps/compliance/catalog.py. Do not edit by hand. -->\n"
)
_NAMES = {"US": "United States", "IN": "India", "ALL": "Both countries"}
_STATUS = {
    catalog.NS: "Not started",
    catalog.IP: "In progress",
    catalog.DONE: "Implemented, not verified",
}


def _cell(text: str) -> str:
    return " ".join(text.split()).replace("|", "\\|")


def render_matrix() -> str:
    out = [
        HEADER,
        "# Regulatory requirements matrix (spec 13, 26.7)\n",
        "An engineering summary to organise the work, **not legal advice**. Qualified counsel must "
        "confirm what applies, the wording and the dates (spec 26.7). The status here is the "
        "**starting** status; the live status, owner and evidence are on the **Compliance** page. "
        '"Implemented" means the software supports it, not that the hospital is compliant.\n',
    ]
    for jurisdiction in ("US", "IN", "ALL"):
        out += [
            f"## {_NAMES[jurisdiction]}\n",
            "| Code | Law | Citation | Requirement | What the law asks | What HIMS does | "
            "Starting status |",
            "|---|---|---|---|---|---|---|",
        ]
        for (
            code,
            where,
            regulation,
            citation,
            title,
            summary,
            support,
            start,
        ) in catalog.REQUIREMENTS:
            if where == jurisdiction:
                cells = [code, regulation, citation, title, summary, support, _STATUS[start]]
                out.append("| " + " | ".join(_cell(cell) for cell in cells) + " |")
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def render_risks() -> str:
    out = [
        HEADER,
        "# Risk register: starting entries (spec 23; HIPAA 164.308(a)(1))\n",
        "Score = likelihood x impact (each 1 to 5). The live register, with owners, treatment and "
        "review dates, is on the **Compliance** page. Explained in "
        "[threat-model.md](threat-model.md). These are engineering estimates for the hospital's "
        "own risk assessment.\n",
        "| Code | Risk | Area | Likelihood | Impact | Score | What reduces it |",
        "|---|---|---|---|---|---|---|",
    ]
    rows = sorted(catalog.RISKS, key=lambda risk: (-risk[4] * risk[5], risk[0]))
    for code, title, description, category, likelihood, impact, mitigation in rows:
        cells = [
            code,
            f"**{title}**: {description}",
            category,
            str(likelihood),
            str(impact),
            str(likelihood * impact),
            mitigation,
        ]
        out.append("| " + " | ".join(_cell(cell) for cell in cells) + " |")
    return "\n".join(out).rstrip() + "\n"


def outputs() -> dict[Path, str]:
    return {MATRIX: render_matrix(), RISKS: render_risks()}
